package com.minenorth_eurobank.braquage.item;
import com.minenorth_eurobank.EuroBank; import com.minenorth_eurobank.braquage.block.ModBlocks; import net.minecraft.core.registries.Registries; import net.minecraft.network.chat.Component; import net.minecraft.world.item.CreativeModeTab; import net.minecraft.world.item.ItemStack; import net.minecraftforge.registries.DeferredRegister; import net.minecraftforge.registries.RegistryObject;
public class ModCreativeTabs{public static final DeferredRegister<CreativeModeTab>TABS=DeferredRegister.create(Registries.CREATIVE_MODE_TAB,EuroBank.MODID); public static final RegistryObject<CreativeModeTab> MINENORTH_TAB=TABS.register("minenorth_banque",()->CreativeModeTab.builder().title(Component.literal("MineNorth Banque")).icon(()->new ItemStack(ModItems.DRILL.get())).displayItems((p,o)->{o.accept(ModItems.DRILL.get());o.accept(ModItems.DRILL_MK2.get());o.accept(ModItems.DRILL_MK3.get());o.accept(ModItems.HACKER.get());o.accept(ModBlocks.BANK_VAULT.get());}).build());}
